L('// ===== NPC SPRITES (40x56) =====')
L('function drawNPCBase(c,cx,pal){const O=1;const headY=10,bodyY=18,legY=36;c.ellipse(cx,headY,5,6,pal[14]);c.ellipse(cx-1,headY-1,4,5,pal[15]);c.ellipse(cx+1,headY+1,3,4,pal[16]);c.set(cx-2,headY-2,pal[17]);c.set(cx+2,headY-2,pal[17]);c.set(cx-2,headY,pal[18]);c.set(cx+2,headY,pal[18]);c.rect(cx-7,bodyY,14,16,pal[9]);c.rect(cx-6,bodyY,12,14,pal[10]);c.rect(cx-5,bodyY+1,8,12,pal[11]);c.line(cx-5,bodyY+1,cx-5,bodyY+13,pal[12]);c.line(cx+3,bodyY+1,cx+3,bodyY+13,pal[12]);c.rect(cx-8,bodyY+14,12,2,pal[12]);c.rect(cx-5,legY,4,7,pal[9]);c.rect(cx+1,legY,4,7,pal[9]);c.set(cx-5,legY,pal[10]);c.set(cx+1,legY,pal[10]);c.rect(cx-6,legY+7,5,3,pal[13]);c.rect(cx,legY+7,5,3,pal[13]);c.set(cx-6,legY+7,pal[14]);c.set(cx,legY+7,pal[14]);c.ellipse(cx-9,bodyY+2,3,3,pal[9]);c.ellipse(cx+8,bodyY+2,3,3,pal[9]);c.outline(O)}')

