L('// ===== EFFECT SPRITES =====')
L('function slashArc(){const c=new PixelCanvas(24,24);for(let i=0;i<12;i++){const a=i*Math.PI/6;const r=8;const x=Math.round(12+Math.cos(a)*r),y=Math.round(12+Math.sin(a)*r);if(x>=0&&x<24&&y>=0&&y<24)c.set(x,y,i<6?40:41)}c.set(6,6,42);c.set(7,5,43);c.outline(1);return c.toFrame()}')
L('function fireball(){const c=new PixelCanvas(24,24);c.ellipse(12,12,7,7,44);c.ellipse(11,11,6,6,45);c.ellipse(10,10,4,4,46);c.ellipse(13,13,5,4,44);c.set(9,9,47);c.set(14,12,47);c.set(10,14,48);c.set(11,8,47);c.set(13,7,47);c.outline(1);return c.toFrame()}')
