L('function levelUpBurst(){const c=new PixelCanvas(24,24);c.ellipse(12,12,10,10,57);c.ellipse(11,11,8,8,58);for(let i=0;i<8;i++){const a=i*Math.PI/4;const r=10;const x=Math.round(12+Math.cos(a)*r),y=Math.round(12+Math.sin(a)*r);if(x>=0&&x<24&&y>=0&&y<24)c.set(x,y,59)}c.set(12,2,59);c.set(12,22,59);c.set(2,12,59);c.set(22,12,59);c.set(12,12,60);c.outline(1);return c.toFrame()}')
